function apiOrigin() {
  return (process.env.ALPHALAB_API_ORIGIN || 'http://127.0.0.1:8000').replace(/\/+$/, '')
}

async function run(input) {
  const id = encodeURIComponent(String(input.strategy_id || '').trim())
  if (!id) throw new Error('strategy_id is required')
  const response = await fetch(apiOrigin() + '/api/strategies/' + id, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error('AlphaLab API ' + response.status + ': ' + await response.text())
  return response.json()
}
